/*
 * Modified by Actuna Sp. z o.o.:
 *   new module (#8): holds the requests to the routes of the nodes (httpNode)
 *   while the flows are restarted by a deployment or a reload from storage;
 *   only requests without a route at the moment of arrival are held
 * This notice is required by section 4(b) of the Apache License 2.0.
 */

/**
 * Holding of the requests to the routes of the nodes during a restart of the
 * flows (#8).
 *
 * The routes that nodes register on `RED.httpNode` (for example `http in`) are
 * removed when the nodes stop and added when the new nodes start, so a request
 * that arrives in between would get 404 from the router. With
 * `deploy.holdHttpNodeRequests.enabled: true` the middleware of this module,
 * mounted on the httpNode app before any route of a node, holds such a request
 * until the new flows have started.
 *
 * Only a request for which the httpNode app has no route at the moment is held:
 * a route of a node that the deployment does not touch (a partial deployment,
 * type `nodes`/`flows`) still answers and is served at once. A route is a layer of
 * the router of the app created by `app.get/post/put/patch/delete/...` that
 * matches the path and the method (HEAD matches a GET route, as in Express); a
 * handler mounted with `app.use` is not a route and does not count, so a request
 * that only such a handler would answer is held during the restart. Without the
 * router of the app (`req.app._router`) every request is held.
 *
 * The signal is the instance state (runtime/lib/state.js, E-02): the requests
 * are held while the state is `deploying` (deploy pipeline step 4 to 8,
 * flows/pipeline.js `deploy`) or `reloading` (a reload from storage, Z-09,
 * flows/pipeline.js `reloadFromStorage`). Both states end - through
 * `instanceState.end()` - only after the start of the new flows completed
 * (flows/pipeline.js `endWithStart`), so the new routes exist when the held
 * requests are released. The states `reloadPending` (the drain) and `ready`
 * are not held: the old routes still answer during the drain. The initial
 * start of the runtime (`starting`), `POST /flows/state` and project switches
 * are not covered.
 *
 * Settings (`deploy.holdHttpNodeRequests`, default off):
 *  - `enabled` (boolean): only `true` enables the hold
 *  - `timeout` (ms, default 5000, at most 2147483647): the longest hold of one request; then 503
 *  - `maxPending` (integer, default 1000): the most requests held at once
 *    (global, not per client); more requests get 503 at once
 *  - `retryAfter` (seconds, default 1): the `Retry-After` header of the 503
 *
 * Responses (JSON, `Cache-Control: no-store`): 503 `{code: "http_hold_timeout"}`
 * or `{code: "http_hold_queue_full"}` or, when releasing a request throws,
 * `{code: "http_hold_release_failed"}`, all with `Retry-After`. Static files under the same
 * root and CORS preflight requests are held as well; the 503 has no `Access-Control-*` headers.
 *
 * A held request is released to the normal routing when the state leaves
 * `deploying`/`reloading` - also when the start failed (`failed`), the flows
 * are stopped (`idle`) or the runtime stops: the router then answers whatever
 * the routes of the running nodes say (404 for a route that does not exist).
 * Requests that are already processed are not affected; the admin API and the
 * editor are not behind this middleware (it is mounted on the httpNode app only).
 * @module
 */

const { log } = require("@node-red/util");
const instanceState = require("./state");

const DEFAULTS = { timeout: 5000, maxPending: 1000, retryAfter: 1 };
// The largest delay of setTimeout: a larger one fires after 1 ms
const MAX_TIMEOUT = 2147483647;
const HOLD_STATES = ["deploying", "reloading"];

let config = { enabled: false };
// The held requests: [{res, next, timer, onClose}], in the order of arrival
let held = [];
let unsubscribe = null;
// Whether the instance state is one of HOLD_STATES, kept by onState()
let holding = false;

function isPositiveNumber(value) {
    return typeof value === "number" && isFinite(value) && value > 0;
}

function isPositiveInteger(value) {
    return Number.isInteger(value) && value > 0;
}

function readConfig(settings) {
    const deploy = (settings && settings.deploy) || {};
    const raw = deploy.holdHttpNodeRequests;
    if (raw === undefined || raw === null) {
        return { enabled: false };
    }
    if (typeof raw !== "object" || Array.isArray(raw)) {
        log.warn(log._("httpHold.invalid-setting", { value: String(raw) }));
        return { enabled: false };
    }
    const result = Object.assign({ enabled: raw.enabled === true }, DEFAULTS);
    [["timeout", value => isPositiveNumber(value) && value <= MAX_TIMEOUT], ["maxPending", isPositiveInteger], ["retryAfter", isPositiveInteger]].forEach(function(entry) {
        const key = entry[0];
        if (raw[key] !== undefined) {
            if (entry[1](raw[key])) {
                result[key] = raw[key];
            } else {
                log.warn(log._("httpHold.invalid-option", { key: key, value: String(raw[key]) }));
            }
        }
    });
    return result;
}

/**
 * Reads the settings and subscribes to the instance state. Calling it again
 * (tests, an embedding application) first releases the held requests.
 * @param {Object} userSettings - the runtime settings (`deploy.holdHttpNodeRequests`)
 */
function init(userSettings) {
    dispose();
    config = readConfig(userSettings);
    if (config.enabled) {
        holding = HOLD_STATES.indexOf(instanceState.get().state) !== -1;
        unsubscribe = instanceState.onChange(onState);
    }
}

/**
 * Unsubscribes from the instance state and releases the held requests.
 */
function dispose() {
    if (unsubscribe) {
        unsubscribe();
        unsubscribe = null;
    }
    config = { enabled: false };
    holding = false;
    releaseAll();
}

/**
 * @return {boolean} whether the hold is enabled (the middleware is to be mounted)
 */
function isEnabled() {
    return config.enabled === true;
}

/**
 * @return {number} the number of the requests held now
 */
function pending() {
    return held.length;
}

/**
 * Whether the route of the Express route layer handles the method (the logic of
 * Route#_handles_method: HEAD falls back to a GET route).
 */
function routeHandlesMethod(route, method) {
    const methods = route.methods || {};
    if (methods._all) {
        return true;
    }
    let name = typeof method === "string" ? method.toLowerCase() : method;
    if (name === "head" && !methods.head) {
        name = "get";
    }
    return Boolean(methods[name]);
}

/**
 * Whether the app that handles the request has a route for it now. The path is
 * relative to the mount point of the app (`req.path`), like the router matches it.
 * An OPTIONS request counts as served when a route matches the path, because the
 * router answers it itself (`Allow`) when no route handles OPTIONS explicitly.
 * @return {boolean} false when it cannot be determined (no router)
 */
function hasRoute(req) {
    const router = req.app && req.app._router;
    if (!router || !Array.isArray(router.stack)) {
        return false;
    }
    const path = req.path;
    return router.stack.some(function(layer) {
        if (!layer.route || !layer.match(path)) {
            return false;
        }
        return req.method === "OPTIONS" || routeHandlesMethod(layer.route, req.method);
    });
}

function onState(info) {
    holding = HOLD_STATES.indexOf(info.state) !== -1;
    if (!holding) {
        releaseAll();
    }
}

function reject(res, req, code, message) {
    const body = JSON.stringify({ code: code, message: message });
    res.statusCode = 503;
    res.setHeader("Retry-After", String(config.retryAfter || DEFAULTS.retryAfter));
    res.setHeader("Cache-Control", "no-store");
    res.setHeader("Content-Type", "application/json; charset=utf-8");
    res.setHeader("Content-Length", Buffer.byteLength(body));
    res.end(req.method === "HEAD" ? undefined : body);
}

function remove(entry) {
    clearTimeout(entry.timer);
    entry.res.removeListener("close", entry.onClose);
    const index = held.indexOf(entry);
    if (index !== -1) {
        held.splice(index, 1);
    }
}

function releaseAll() {
    const entries = held;
    held = [];
    entries.forEach(function(entry) {
        clearTimeout(entry.timer);
        entry.res.removeListener("close", entry.onClose);
    });
    // A failing next() must not drop the other requests (their timers are cleared)
    entries.forEach(function(entry) {
        try {
            entry.next();
        } catch (err) {
            log.warn(log._("httpHold.release-failed", { message: (err && err.message) || String(err) }));
            if (!entry.res.headersSent) {
                reject(entry.res, entry.req, "http_hold_release_failed", "The flows restarted but the request could not be processed");
            }
        }
    });
}

/**
 * The Express middleware to be mounted on the httpNode app before any route
 * of a node. Passes the request on at once unless a restart of the flows runs
 * and the app has no route for the request.
 */
function middleware(req, res, next) {
    if (!config.enabled || !holding || hasRoute(req)) {
        return next();
    }
    if (held.length >= config.maxPending) {
        return reject(res, req, "http_hold_queue_full", "The flows are restarting and too many requests are waiting");
    }
    const entry = { req: req, res: res, next: next };
    entry.timer = setTimeout(function() {
        remove(entry);
        reject(res, req, "http_hold_timeout", "The flows are restarting, try again");
    }, config.timeout);
    // The client gave up while the request was held
    entry.onClose = function() { remove(entry) };
    res.on("close", entry.onClose);
    held.push(entry);
}

module.exports = {
    init,
    dispose,
    isEnabled,
    pending,
    middleware
};
